"example": "FDE 给某企业销售部做「商机跟进助手」：Skill 写清跟进话术和步骤，连接器经 MCP 接入现有 CRM（不替换原系统），资料库打通腾讯文档里的产品资料，再把三者打包成一个「销售专家」角色给全员调用。若只写一段提示词就上线，就成了「换皮提示词」。",
