"icon": "search",
"example": "某财务共享中心的 Agent 上线前，FDE 做审计演练：假设三个月后出了一笔错误结算，能否查到谁改过结算 Skill 的配置、连接器调了哪个系统返回了什么、哪位主管点了终审确认？演练中还发现 tool_output 里存了客户手机号明文，随即做脱敏（mask）并把敏感字段隔离到加密日志库。",
