"example": "客户部署了连内部知识库的 MCP Server：客服在工作台登录后用 Agent，选 OAuth 2.1，跳授权页点「同意」拿 access_token；每天凌晨 2 点自动跑的索引更新没人在场，管理员预生成 PAT 存进密钥管理服务；对方授权服务器还没升到 2.1，就先用 OAuth 2.0 过渡并推动升级。",
